// @@ en/index.html:2676
  // ---- fork alignment ------------------------------------------------------
  // A parallel pair (.stagegroup) is symmetric about its caption band, so its
  // spine sits far lower in its own box than an ungrouped marker's centre does
  // in its box. Measure that difference once and publish it as --sg-lift: the
  // group pulls itself up by it, .track absorbs the same amount as padding, and
  // every marker plus the fork's spine ends up on one line. Measured rather
  // than hard-coded because the branch labels wrap differently by width, font
  // and zoom. With nothing measurable it stays 0 and the fork hangs below the
  // line — degraded, not broken. ("With no JS" is not a case: #board is empty
  // in the markup and every row here is built by this script, so a no-script
  // reader gets the failure banner, never a half-drawn fork.)
  function alignStageForks() {
    // Per track, not once globally: a branch only renders its year line when
    // that gate has a real year, so an all-idle pair (GanLum) is shorter than
    // a cleared one (ASPY) and needs a different lift. --sg-lift is set on the
    // .track itself and inherits to both the padding and the group's margin.
    document.querySelectorAll(".track").forEach(track => {
      const group = track.querySelector(".stagegroup");
      if (!group) return;
      track.style.setProperty("--sg-lift", "0px");
      const note = group.querySelector(".stagegroup-note");
      const mark = group.querySelector(".smark");
      if (!note || !mark) return;
      const nr = note.getBoundingClientRect();
      // spine: centre of the caption band, measured from the group's own top
      const spine = (nr.top + nr.bottom) / 2 - group.getBoundingClientRect().top;
      // not rounded: a half-pixel of rounding here shows up as the spine
      // sitting 1px off the neighbouring markers' centreline
      const lift = Math.max(0, spine - mark.offsetHeight / 2);
      track.style.setProperty("--sg-lift", lift.toFixed(2) + "px");
    });
  }

