  // ---- fork strokes --------------------------------------------------------
  // One path per side into the .forkline overlay: arm, rounded corner, spine,
  // corner, arm, drawn from where the two markers actually ended up. Two
  // strokes never have to meet, which is the whole point — see the CSS block
  // for the two ways the old border-corner version failed to.
  //
  // Pairs only: this attaches the FIRST and LAST marker in the group. A column
  // of three would need an arm per marker and would currently leave the middle
  // one unattached. validate-data.js permits such a column; no dataset has one.
  const FORK_R = 10;          // corner radius, on the stroke's centreline

// @@ en/index.html:2708
  const FORK_NODE = 4.5;      // radius of the node sitting on the junction

// @@ en/index.html:2709
  function drawStageForks() {
    document.querySelectorAll(".stagegroup").forEach(group => {
      const svg = group.querySelector(".forkline");
      const marks = group.querySelectorAll(".smark");
      if (!svg || marks.length < 2) return;
      const gr = group.getBoundingClientRect();
      if (!gr.width || !gr.height) return;   // not laid out (or hidden) yet
      const top = marks[0].getBoundingClientRect();
      const bot = marks[marks.length - 1].getBoundingClientRect();
      const w = gr.width, h = gr.height, R = FORK_R;
      // Deliberately unrounded, for the same reason --sg-lift is: the spine's
      // midpoint has to land exactly on the centreline that lift put the
      // neighbouring columns' bars on. Snapping these to the pixel grid would
      // reintroduce a half-pixel jog at the one junction this exists to close.
      const yT = top.top - gr.top + top.height / 2;
      const yB = bot.top - gr.top + bot.height / 2;
      // the arms stop at the marker's own 4px gap, where .bar used to end
      const xIn = top.left - gr.left - 4;
      const xOut = top.right - gr.left + 4;
      const spine = (yT + yB) / 2;
      svg.setAttribute("viewBox", `0 0 ${w} ${h}`);
      svg.innerHTML =
        `<path class="fk-arm is-in" d="M ${xIn} ${yT} H ${R}` +
          ` A ${R} ${R} 0 0 0 0 ${yT + R} V ${yB - R}` +
          ` A ${R} ${R} 0 0 0 ${R} ${yB} H ${xIn}"/>` +
        `<path class="fk-arm is-out" d="M ${xOut} ${yT} H ${w - R}` +
          ` A ${R} ${R} 0 0 1 ${w} ${yT + R} V ${yB - R}` +
          ` A ${R} ${R} 0 0 1 ${w - R} ${yB} H ${xOut}"/>` +
        `<circle class="fk-node is-in" cx="0" cy="${spine}" r="${FORK_NODE}"/>` +
        `<circle class="fk-node is-out" cx="${w}" cy="${spine}" r="${FORK_NODE}"/>`;
    });
  }

